namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int PayableCents(string tier, int subtotalCents)
    {
        var points = Math.Min(TierPoints(tier) + OrderSizePoints(subtotalCents), CeilingPoints);
        var discountCents = subtotalCents * points / 100;

        return subtotalCents - discountCents;
    }

    private static int TierPoints(string tier) => tier switch
    {
        "Bronze" => 5,
        "Silver" => 7,
        "Gold" => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, "Unknown loyalty tier."),
    };

    private static int OrderSizePoints(int subtotalCents) => subtotalCents switch
    {
        < 5000 => 0,
        < 20000 => 1,
        _ => 3,
    };
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public int For(string tier, int subtotalCents)
    {
        return LoyaltyDiscount.PayableCents(tier, subtotalCents);
    }
}
E
